# glibc rand() sim is complex; use ctypes to call libc directly
import ctypes
libc=ctypes.CDLL("libc.so.6")
def libc_drand48(seed,n,skip=0):
    libc.srand48(ctypes.c_long(seed))
    libc.drand48.restype=ctypes.c_double
    for _ in range(skip): libc.drand48()
    return [libc.drand48() for _ in range(n)]
def libc_rand(seed,n,skip=0):
    libc.srand(ctypes.c_uint(seed))
    for _ in range(skip): libc.rand()
    return [libc.rand()/2147483647.0 for _ in range(n)]
